 async Task<JsonObject> TicketInput(JsonObject b,JsonObject reporter){var config=await s.All("config");var service=config.FirstOrDefault(c=>c.S("id")==b.S("serviceId")&&c.S("kind")=="servicios"&&c.B("activo"));var category=config.FirstOrDefault(c=>c.S("id")==b.S("categoryId")&&c.S("kind")=="categorias"&&c.B("activo"));Require((b.S("serviceId")==""||service!=null)&&(b.S("categoryId")==""||category!=null&&(category.S("serviceId")==""||category.S("serviceId")==b.S("serviceId"))),400,"Servicio o categoría no válidos.");var areaId=b.S("areaId");if(areaId=="")areaId=reporter.S("areaId");var area=config.FirstOrDefault(c=>c.S("id")==areaId&&c.S("kind")=="areas"&&c.B("activo"));Require(areaId==""||area!=null,400,"Área no válida.");Require(Admin(u)||areaId==""||reporter.A("areas").Has(areaId),403,"El área no está autorizada para tu cuenta.");var priority=b.I("prioridad");Require(priority is >=1 and <=4,400,"Prioridad no válida.");var custom=new JsonObject();foreach(var f in service.A("fields").Items()){if(f.B("internal")&&!p.B("internos"))continue;var value=b.O("custom").S(f.S("id")).Trim();Require(!f.B("required")||value!="",400,"Completa "+f.S("label")+".");Require(value.Length<=4000&&(value==""||f.S("type")!="number"||double.TryParse(value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var number)&&double.IsFinite(number))&&(value==""||f.S("type")!="select"||f.A("options").Has(value)),400,"Valor no válido en "+f.S("label")+".");custom[f.S("id")]=value;}var teamId=p.B("asignar")?b.S("teamId"):"";if(teamId=="")teamId=category.S("teamId");if(teamId=="")teamId=service.S("teamId");Require(teamId==""||config.Any(c=>c.S("id")==teamId&&c.S("kind")=="equipos"&&c.B("activo")),400,"Equipo no válido.");Require(b.S("descripcion").Length<=4000,400,"La descripción admite hasta 4000 caracteres.");return Obj(new{problema=Required(b,"problema","Problema",160),ubicacion=Required(b,"ubicacion","Ubicación",120),descripcion=b.S("descripcion"),prioridad=priority,areaId,areaNombre=area.S("nombre"),serviceId=service.S("id"),serviceNombre=service.S("nombre","Ayuda general"),categoryId=category.S("id"),categoryNombre=category.S("nombre"),teamId,custom,internalFields=service.A("fields").Items().Where(f=>f.B("internal")).Select(f=>f.S("id")).ToArray()});}
 async Task<object> CreateTicket(JsonObject b){Need("crear");var reporter=Admin(u)?await s.Get("users",b.S("reportadoPorId",u.S("id"))):u;Require(reporter!=null&&reporter.B("activo"),400,"Reportante inválido.");var t=await TicketInput(b,reporter!);var id=(await s.Next("tickets")).ToString();var time=Now();var config=await s.All("config");var meta=config.Where(c=>c.S("kind")=="metas"&&c.B("activo")&&c.I("prioridad")==t.I("prioridad")&&(c.S("serviceId")==""||c.S("serviceId")==t.S("serviceId"))).OrderByDescending(c=>c.S("serviceId")!="").FirstOrDefault();var calendar=meta==null?null:config.FirstOrDefault(c=>c.S("id")==meta.S("calendarId"));t=Merge(t,Obj(new{id,estado=1,reportadoPorId=reporter!.S("id"),reportadoPor=reporter.S("nombre"),fechaReporte=time,fechaActualizacion=time,solucion="",tecnicoId="",tecnicoNombre="",eliminado=false,messages=Array.Empty<object>(),historial=new[]{Event("Reporte creado")},meta=meta==null?null:Obj(new{nombre=meta.S("nombre"),responseDue=BusinessCalendar.Due(time,meta.D("responseHours"),calendar),resolutionDue=BusinessCalendar.Due(time,meta.D("resolutionHours"),calendar),calendar})}));t=await s.Save("tickets",t);await Notify(t,$"Nuevo reporte CF-{id.PadLeft(4,'0')}: {t.S("problema")}",excludeActor:false);return SafeTicket(t,p);}
 async Task<object> TicketApi(string path,string method,JsonObject b,IQueryCollection query){var parts=path.Split('/');Require(parts.Length is 2 or 3,404,"Ruta no encontrada.");var t=await s.Get("tickets",parts[1]);Require(t!=null&&!t.B("eliminado")&&See(u,p,t),404,"Reporte no encontrado.");var action=parts.Length==3?parts[2]:"";if(method=="GET"&&action=="")return SafeTicket(t,p);if(method=="DELETE"&&query.ContainsKey("version")){Require(int.TryParse(query["version"],out var v)&&v==t.I("_v"),409,"El reporte cambió en otra sesión. Actualiza el detalle.");}else Version(t,b);var title="";bool internalOnly=false;
