  else if(action=="asignar"&&method=="PUT"){Need("asignar");if(t.I("estado")==4&&!t.ContainsKey("resolvedTechnicianId"))FreezeTechnician(t);var tech=b.S("tecnicoId")==""?null:await s.Get("users",b.S("tecnicoId"));Require(b.S("tecnicoId")==""||tech!=null&&tech.B("activo")&&tech.S("role")=="Técnico",400,"Selecciona un técnico activo.");if(tech!=null&&t.S("teamId")!=""){var team=await s.Get("config",t.S("teamId"));Require(team.A("members").Count==0||team.A("members").Has(tech.S("id")),400,"El técnico no pertenece al equipo responsable.");}t["tecnicoId"]=tech.S("id");t["tecnicoNombre"]=tech.S("nombre");title=tech==null?"Asignación retirada":"Técnico asignado: "+tech.S("nombre");}
  else if(action=="estado"&&method=="PATCH"){Need("avanzar");Require(Attend(u,t),403,"Solo el técnico asignado puede atender este reporte.");Require(b.I("estado")==t.I("estado")+1&&t.I("estado")<4,409,"Solo puedes avanzar al siguiente estado.");Require(b.I("estado")!=4||t.S("solucion").Trim()!="",400,"Documenta la solución antes de cerrar el ticket.");title=$"Estado {t.I("estado")} → {b.I("estado")}";t["estado"]=b.I("estado");if(t.I("estado")==4){t["fechaSolucion"]=Now();FreezeTechnician(t);}}
  else if(action=="solucion"&&method=="PUT"){Need("solucion");Require(Attend(u,t),403,"Solo el técnico asignado puede resolverlo.");t["solucion"]=Required(b,"solucion","Solución",4000);title="Solución documentada";if(b.B("cerrar")){Need("avanzar");Require(t.I("estado")==3,409,"El reporte debe estar en reparación antes de solucionarlo.");t["estado"]=4;t["fechaSolucion"]=Now();FreezeTechnician(t);title="Solución documentada y estado En reparación → Solucionado";}}
  else if(action=="valoracion"&&method=="PUT"){Require(t.S("reportadoPorId")==u.S("id"),403,"Solo quien reportó la incidencia puede valorar su atención.");Require(t.I("estado")==4,409,"La atención se puede valorar cuando el ticket está solucionado.");var technician=t.S("resolvedTechnicianId",t.S("tecnicoId"));Require(technician!=""&&technician!=u.S("id"),403,"La valoración requiere un técnico responsable distinto del solicitante.");Require(b.I("score") is >=1 and <=5,400,"Selecciona una valoración de 1 a 5 estrellas.");Require(b.S("comment").Length<=1000,400,"El comentario admite hasta 1000 caracteres.");t["resolvedTechnicianId"]=technician;t["resolvedTechnicianName"]=t.S("resolvedTechnicianName",t.S("tecnicoNombre"));t["rating"]=Obj(new{score=b.I("score"),comment=b.S("comment").Trim(),userId=u.S("id"),technicianId=technician,technicianName=t.S("resolvedTechnicianName"),fecha=Now()});title="Valoración de atención actualizada";}
  else if(action=="mensajes"&&method=="POST"){Require(t.S("reportadoPorId")==u.S("id")||Attend(u,t),403,"Solo los participantes pueden responder a este reporte.");internalOnly=b.B("internal");Require(!internalOnly||p.B("internos"),403,"No puedes añadir notas internas.");var text=Required(b,"text","Respuesta",4000);JsonObject? file=null;if(b["file"] is JsonObject f){Require(new[]{"application/pdf","image/png","image/jpeg","text/plain"}.Contains(f.S("type"))&&f.S("data").Length<=350000,400,"Formato o tamaño no permitido.");byte[] bytes;try{bytes=Convert.FromBase64String(f.S("data"));}catch{throw new ApiError(400,"Archivo no válido.");}Require(bytes.Length<=256000,400,"El archivo supera los 250 KB.");var valid=f.S("type") switch{"application/pdf"=>bytes.AsSpan().StartsWith("%PDF-"u8),"image/png"=>bytes.AsSpan().StartsWith(new byte[]{137,80,78,71}),"image/jpeg"=>bytes.AsSpan().StartsWith(new byte[]{255,216}),_=>!bytes.Contains((byte)0)};Require(valid,400,"El contenido no corresponde al formato indicado.");var key=t.S("id")+"/"+Id();var name=Required(f,"name","Nombre de archivo",180);await s.PutFile(new Archivo{Key=key,Name=name,Type=f.S("type"),Content=bytes});file=Obj(new{key,name,type=f.S("type"),size=bytes.Length});}var messages=t.A("messages");if(!t.ContainsKey("messages"))t["messages"]=messages;messages.Add(Obj(new{id=Id(),userId=u.S("id"),author=u.S("nombre"),text,@internal=internalOnly,fecha=Now(),file}));if(!internalOnly&&u.S("id")!=t.S("reportadoPorId")&&t.S("firstResponseAt")=="")t["firstResponseAt"]=Now();title=internalOnly?"Nota interna añadida":"Respuesta añadida";}
  else throw new ApiError(405,"Operación no permitida.");t["fechaActualizacion"]=Now();var history=t.A("historial");if(!t.ContainsKey("historial"))t["historial"]=history;history.Add(Event(title,internalOnly));t=await s.Save("tickets",t);await Notify(t,$"CF-{t.S("id").PadLeft(4,'0')}: {title}",internalOnly);return SafeTicket(t,p);
 }
